// Extra drinks added on top of the shared drinks.json, each with its own step-by-step guide.
// Steps are built from small helpers so every guide follows the same wording as guides.json.
const HINT = { 50: "the 50 side", 25: "the 25 side", 12.5: "half a 25", 75: "50 + 25", 100: "50 + 50" };
function item(line) {
  const m = line.match(/^([\d.]+) ml (.*)$/);
  if (m) return { ml: +m[1], item: m[2], hint: HINT[m[1]] || null, note: null, role: "mix" };
  const tm = line.match(/^Top ([\d.]+) ml (.*)$/);
  if (tm) return { ml: +tm[1], item: tm[2], hint: HINT[tm[1]] || null, note: null, role: "top" };
  const t = line.match(/^Top (.*)$/);
  if (t) return { ml: null, item: t[1], hint: null, note: null, role: "top" };
  return { ml: null, item: line, hint: null, note: null, role: "mix" };
}
const pick = (spec, re) => spec.filter((l) => re.test(l)).map(item);
const ICE_WORD = { cubed: "cubed ice", crushed: "crushed ice", large: "1 large cube" };

const S = {
  chill: (glass) => ({ scene: "chill", title: "Chill the glass", text: `Fill the ${glass} with ice and water. Tip it out just before you pour.` }),
  rim: (rim, text) => ({ scene: "rim", title: "Rim the glass", text, rim }),
  ice: (kind, glass) => ({ scene: "ice", title: "Ice the glass", text: kind === "large" ? `Put 1 large cube in the ${glass}.` : `Fill the ${glass} to the top with ${ICE_WORD[kind]}.`, ice: kind }),
  tin: (items) => ({ scene: "pourTin", title: "Pour into the tin", text: "Measure each one with the jigger and pour it into the shaker tin.", items }),
  mix: (items) => ({ scene: "pourMix", title: "Pour into the mixing glass", text: "Measure each one with the jigger. Pour into the mixing glass.", items }),
  glass: (items, text = "Measure each one with the jigger and pour over the ice.") => ({ scene: "pourGlass", title: "Pour into the glass", text, items }),
  shake: (text = "Fill the tin with ice. Seal it and shake hard for 10 to 12 seconds.") => ({ scene: "shake", title: "Shake", text }),
  dry: () => ({ scene: "dryShake", title: "Dry shake", text: "Seal the tin with no ice. Shake hard for 10 seconds to whip up the foam." }),
  shakeAgain: () => ({ scene: "shake", title: "Shake again with ice", text: "Open the tin, fill it with ice, seal it and shake hard for another 10 seconds." }),
  stir: (secs = 30) => ({ scene: "stir", title: "Stir", text: `Fill the mixing glass with ice. Stir smoothly for ${secs} seconds.` }),
  strainMix: (text) => ({ scene: "strainMix", title: "Strain", text }),
  strain: (text, double = false) => ({ scene: "strain", title: double ? "Double strain" : "Strain", text, double }),
  strainShot: () => ({ scene: "strain", title: "Strain", text: "Strain into the shot glass. Fill it to just below the rim.", double: false, shot: true }),
  muddle: (items, text, title = "Press the fruit") => ({ scene: "muddle", title, text, items, inGlass: true }),
  top: (items, text = "Top up slowly to just below the rim.") => ({ scene: "top", title: "Top up", text, items }),
  lift: (text = "Give it a short stir with the bar spoon.") => ({ scene: "lift", title: "Short stir", text }),
  churn: (text) => ({ scene: "lift", title: "Churn", text }),
  float: (items, text) => ({ scene: "float", title: "Float", text, items }),
  layer: (items, text, bands) => ({ scene: "layer", title: `Then ${items[0].item}`, text, items, bands }),
  shot: (items, title, text) => ({ scene: "pourShot", title, text, items }),
  garnish: (g, extra = "Serve straight away.") => ({ scene: "garnish", title: "Garnish and serve", text: `${g}. ${extra}`, garnish: g }),
  serve: (text) => ({ scene: "serve", title: "Serve", text }),
  sink: (items, title, text) => ({ scene: "sink", title, text, items }),
  can: (items) => ({ scene: "can", title: "Pour the Red Bull", text: "Pour half a can of chilled Red Bull into a rocks glass. No ice.", items }),
  half: (items, text) => ({ scene: "half", title: "Pour the beer", text, items }),
  side: (text, pair) => ({ scene: "side", title: "Serve side by side", text, pair }),
};
// A Red Bull bomb: the shot and half a can, served side by side for the guest to drop in.
const BOMB_METHOD = "Pour the shot. Pour half a can of Red Bull into a rocks glass. Serve side by side, guest drops the shot in";
const DROP_IT = "Serve them together. The guest drops the shot into the Red Bull. Check ID.";
const bomb = (name, shot, blurb, colour, tags = ["Sweet", "Energy"]) => ({ section: "Bombs & Boilermakers", name, tags, blurb, glass: "Shot glass in a rocks glass", ice: "None", colour,
  method: BOMB_METHOD, spec: [shot, "125 ml Red Bull"], garnish: "None",
  steps: () => [S.shot([item(shot)], "Pour the shot", "Measure with the jigger into a shot glass."), S.can([item("125 ml Red Bull")]), S.side(DROP_IT)] });
// A layered shot: the first one poured, the rest floated over a bar spoon. bands are the colours, bottom first.
const layered = (spec, bands) => [S.shot([item(spec[0])], `${item(spec[0]).item} first`, `Pour ${spec[0]} into the shot glass.`),
  ...spec.slice(1).map((l, i) => S.layer([item(l)], i === spec.length - 2 ? "Pour it slowly over the back of a bar spoon to make the top layer." : "Pour it slowly over the back of a bar spoon so it sits on top.", bands.slice(0, i + 2))),
  S.serve("Serve without stirring so the layers stay clean. Check ID if the guest looks under 25.")];
const ALL = /./;
const NOT_TOP = (l) => !/^Top /.test(l);
const TOPS = /^Top /;
const ID = "Serve straight away. Check ID if the guest looks under 25.";
const UP = "Hawthorne strainer on the tin, fine strainer over the glass. Strain into the chilled coupe.";

// Shapes the 5 Nov 2026 additions share, so each new drink is one line of data and one of steps.
const HEAT = { scene: "heat", title: "Warm the glass", text: "Fill the heatproof glass with hot water. Tip it out after a minute." };
const built = (sp, g, glass = "highball") => [S.ice("cubed", glass), S.glass(pick(sp, /^\d/)), S.top(pick(sp, TOPS)), S.lift(), S.garnish(g)];
const upShake = (sp, g, extra) => [S.chill("coupe"), S.tin(pick(sp, ALL)), S.shake(), S.strain(UP, true), S.garnish(g, extra)];
const upStir = (sp, g) => [S.chill("coupe"), S.mix(pick(sp, ALL)), S.stir(), S.strainMix("Hold the julep strainer on the mixing glass. Strain into the chilled coupe."), S.garnish(g)];
const overIce = (sp, g, ice = "cubed", glass = "rocks glass") => [S.ice(ice, glass), S.tin(pick(sp, /^\d/)), S.shake(), S.strain("Strain over the fresh ice."), S.garnish(g)];
const foamUp = (sp, g) => [S.chill("coupe"), S.tin(pick(sp, ALL)), S.dry(), S.shakeAgain(), S.strain(UP, true), S.garnish(g, "Serve straight away. The foam is foamer drops, no egg.")];
const shotShake = (sp) => [S.tin(pick(sp, ALL)), S.shake("Fill the tin with ice. Seal it and shake hard for 8 seconds."), S.strainShot(), S.serve(ID)];
const fizzUp = (sp, g) => [S.glass(pick(sp, /^\d/), "Measure with the jigger and pour into the coupe."), S.top(pick(sp, TOPS), "Tilt the glass and top up slowly so it doesn't foam over."), S.garnish(g)];
