function tools(steps) {
  const t = ["jigger"], has = (s) => steps.some((x) => x.scene === s);
  if (has("pourTin")) t.push("shaker tin", "Hawthorne strainer");
  if (steps.some((x) => x.double)) t.push("fine strainer");
  if (has("muddle")) t.push("muddler");
  if (has("pourMix")) t.push("mixing glass");
  if (has("stir") || has("lift") || has("float") || has("layer")) t.push("bar spoon");
  if (has("zest")) t.push("peeler");
  return [...new Set(t)];
}
module.exports = (icons) => X.map(({ steps, ...d }) => {
  const st = steps(d.spec).map((s, i) => ({ n: i + 1, ...s }));
  return { drink: { src: "proposed", ...d }, guide: { name: d.name, glassKind: icons.glassKind(d.glass), colour: d.colour, tools: tools(st), steps: st } };
});
